UPDATE maturity_overdue_daily_charge
SET paid_delinquency_charge = paid_delinquency_charge + #{amount}
WHERE maturity_overdue_daily_charge_id = #{maturityOverdueDailyChargeId}



UPDATE maturity_overdue_daily_charge modc
JOIN loan_maturity_overdue m ON m.loan_maturity_overdue_id = modc.loan_maturity_overdue_id
SET modc.delinquency_status_id = #{resolved}
WHERE m.loan_account_id = #{loanAccountId}
  AND modc.delinquency_status_id = #{inProgress}
  AND modc.paid_delinquency_charge >= modc.delinquency_charge
